return out.join('\n');

function describe(node, depth) {
  let s = '';
  const pad = '  '.repeat(depth);
  const t = node.type;
  const rect = (t === 'FRAME'||t==='COMPONENT'||t==='INSTANCE') ? ` w=${Math.round(node.width)} h=${Math.round(node.height)}` : '';
  s += `${pad}${t} "${node.name}" id=${node.id}${rect}`;
  if (t === 'TEXT') {
    s += ` chars="${node.characters.replace(/\n/g,'|')}" fontName=${JSON.stringify({family:node.fontName.family, style:node.fontName.style})} fontSize=${node.fontSize}`;
  }
  if (t === 'COMPONENT' || t==='INSTANCE') {
    s += ` (main=${node.mainComponent ? node.mainComponent.name : '?'})`;
  }
  s += '\n';
  if ('children' in node) {
    for (const c of node.children) s += describe(c, depth+1);
  }
  return s;
}
