function describe2(node, depth) {
  let s = '';
  const pad = '  '.repeat(depth);
  const t = node.type;
  s += `${pad}${t} "${node.name}" id=${node.id}`;
  if (t === 'TEXT') {
    s += ` chars="${node.characters.replace(/\n/g,'|')}"`;
    const fills = node.fills;
    if (Array.isArray(fills)) s += ` fill=${fills.map(f=>f.type+(f.color?'#'+[f.color.r,f.color.g,f.color.b].map(c=>Math.round(c*255).toString(16).padStart(2,'0')).join(''):'')).join(',')}`;
  }
  if (t === 'FRAME' || t==='COMPONENT' || t==='INSTANCE') {
    const fills = node.fills;
    if (Array.isArray(fills)) s += ` fill=${fills.map(f=>f.type+(f.color?'#'+[f.color.r,f.color.g,f.color.b].map(c=>Math.round(c*255).toString(16).padStart(2,'0')).join(''):'')).join(',')}`;
    const strokes = node.strokes;
    if (Array.isArray(strokes) && strokes.length) s += ` stroke=${strokes.map(f=>'#'+[f.color.r,f.color.g,f.color.b].map(c=>Math.round(c*255).toString(16).padStart(2,'0')).join('')).join(',')} strokeW=${node.strokeWeight} corner=${node.cornerRadius}`;
    if (node.effects && node.effects.length) s += ` effects=${node.effects.length}`;
  }
  s += '\n';
  if ('children' in node) for (const c of node.children) s += describe2(c, depth+1);
  return s;
}
