const ws = figma.root.children.find(p => p.name === '03 · Workspace');
const cf = ws.children.find(c=>c.name==='Components');
// compute bounds
let minX=Infinity,maxX=-Infinity,minY=Infinity,maxY=-Infinity;
for(const c of cf.children){
  minX=Math.min(minX,c.x); maxX=Math.max(maxX,c.x+c.width);
  minY=Math.min(minY,c.y); maxY=Math.max(maxY,c.y+c.height);
}
cf.resize(maxX-minX+100, maxY-minY+100);
// reposition children to be positive
const dx = -minX + 50, dy = -minY + 50;
for(const c of cf.children){ c.x += dx; c.y += dy; }
return 'resized to '+Math.round(cf.width)+'x'+Math.round(cf.height);

