async function makeInstance(name, parent, opts){
  const comp = byName[name]; if(!comp) throw new Error('no comp '+name);
  const inst = comp.createInstance(); if(opts&&opts.resize){ inst.resize(opts.resize.w, opts.resize.h);}
  if(opts){ if(opts.x!==undefined) inst.x=opts.x; if(opts.y!==undefined) inst.y=opts.y; }
  parent.appendChild(inst); return inst;
}
