  if(opts && opts.lineHeight!==undefined){ t.lineHeight={value:opts.lineHeight, unit:'PIXELS'}; }
  if(opts && opts.letterSpacing!==undefined){ t.letterSpacing={value:opts.letterSpacing, unit:'PIXELS'}; }
  if(opts && opts.align!==undefined){ t.textAlignHorizontal = opts.align; }
  parent.appendChild(t); return t;
}
function rect(parent, w, h, fill, x, y, opts){
  const r = figma.createRectangle(); r.resize(w,h); r.x=x; r.y=y;
  r.fills = [{type:'SOLID', color: fill}];
  if(opts && opts.cornerRadius) r.cornerRadius = opts.cornerRadius;
  if(opts && opts.stroke){ r.strokes=[{type:'SOLID',color:opts.stroke}]; r.strokeWeight=opts.strokeWeight||1; }
  parent.appendChild(r); return r;
}

