function text(parent, str, x, y, size, weight, color, family, align) {
  const t = figma.createText();
  t.fontName = { family: family || "Poppins", style: weight || "Regular" };
  t.fontSize = size;
  t.characters = str;
  t.fills = [{ type: 'SOLID', color: color || {r:0,g:0,b:0} }];
  if (align) t.textAlignHorizontal = align;
  t.x = x; t.y = y;
  parent.appendChild(t);
  return t;
}
function rect(parent, x, y, w, h, fill, radius) {
  const r = figma.createRectangle();
  r.resize(w, h); r.x = x; r.y = y;
  if (fill) r.fills = [{ type: 'SOLID', color: fill }]; else r.fills = [];
  if (radius) r.cornerRadius = radius;
  parent.appendChild(r);
  return r;
}
function icon(parent, compID, x, y) {
  const c = figma.getNodeById(compID);
  const inst = c.createInstance();
  inst.x = x; inst.y = y;
  parent.appendChild(inst);
  return inst;
}
function field(parent, x, y, w, label, value) {
  text(parent, label, x, y, 15, 'Medium', {r:0.13,g:0.13,b:0.15}, "Poppins");
  const r = rect(parent, x, y+26, w, 54, {r:1,g:1,b:1});
  r.strokes=[{type:'SOLID', color:{r:0.85,g:0.85,b:0.88}}]; r.strokeWeight=1; r.cornerRadius=8;
  if (value) text(parent, value, x+18, y+41, 16, 'Regular', {r:0.33,g:0.33,b:0.37}, "Poppins");
}
function btn(parent, x, y, w, h, label, fill) {
  const r = rect(parent, x, y, w, h, fill||{r:0,g:0,b:0}); r.cornerRadius=8;
  const t = text(parent, label, x, y, h>50?17:15, 'Medium', {r:1,g:1,b:1}, "Poppins", 'CENTER');
  t.resize(w, h); t.textAlignVertical = 'CENTER';
  return r;
}

