const hits=[];
function walk(n){
  if(n.type==='FRAME' || n.type==='COMPONENT' || n.type==='INSTANCE'){
    if(/^(0\d_|1\d_|Components)/.test(n.name)) hits.push(n.name+' type='+n.type+' page='+(n.root? n.root.name : '?')+' id='+n.id+' w='+Math.round(n.width));
  }
  if('children' in n) for(const c of n.children) walk(c);
}
walk(figma.root);
return hits.join('\n') || 'NONE FOUND';

