function placeHotspot(screen, node, pad, dest, label){
  let tb; try{ tb=node.absoluteBoundingBox; }catch(e){ tb=null; }
  let fb; try{ fb=screen.absoluteBoundingBox; }catch(e){ fb=null; }
  if(!tb||!fb) return false;
  const x=tb.x-fb.x-pad, y=tb.y-fb.y-pad, w=tb.width+pad*2, h=tb.height+pad*2;
  const r=figma.createRectangle(); r.name='Hotspot: '+label; r.resize(w,h); r.x=x; r.y=y;
  r.fills=[{type:'SOLID',color:{r:0,g:0,b:0},opacity:0.001}];
  screen.appendChild(r);
  r.reactions=[{trigger:{type:'ON_CLICK'},action:{type:'NAVIGATE',destinationId: dest.id}}];
  log.push('OK '+label+' ->'+dest.name);
  return true;
}
