const home=ws.children.find(c=>c.type==='FRAME'&&c.name==='01_Home');
if(home){ const test=home.children.find(c=>c.name==='test hotspot'); if(test) test.remove(); }
// Arrange frames: place them in a grid on the canvas with clear spacing
const order=['01_Home','02_Shop','03_Product','04_Mini_Cart','05_Cart','06_Checkout','07_Sign_Up','08_Sign_In','09_Forgot_Password','10_Confirmation_Code','11_New_Password'];
let x=0,y=0,rowH=0;
for(const nm of order){ const f=ws.children.find(c=>c.type==='FRAME'&&c.name===nm); if(!f) continue; f.x=x; f.y=y; x+=Math.round(f.width)+80; rowH=Math.max(rowH,f.height); if(x>3000){ x=0; y+=rowH+80; rowH=0; } }
return 'Frames arranged. Workspace current page set.';

const ws=figma.root.children.find(p=>p.name==='03 · Workspace');
await figma.setCurrentPageAsync(ws);
const names=['01_Home','02_Shop','03_Product','04_Mini_Cart','05_Cart','06_Checkout','07_Sign_Up','08_Sign_In','09_Forgot_Password','10_Confirmation_Code','11_New_Password'];
const out=[];
let totalHot=0;
for(const nm of names){
  const f=ws.children.find(c=>c.type==='FRAME'&&c.name===nm);
  if(!f){out.push(nm+' MISSING');continue;}
  const hots=f.children.filter(c=>String(c.name).indexOf('Hotspot')===0);
  totalHot+=hots.length;
  out.push(nm+' id='+f.id+' w='+Math.round(f.width)+' h='+Math.round(f.height)+' hotspots='+hots.length);
}
out.push('TOTAL HOTSPOTS: '+totalHot);
return out.join('\n');

const ws=figma.root.children.find(p=>p.name==='03 · Workspace');
await figma.setCurrentPageAsync(ws);
const out=[];
let total=0, wired=0;
for(const c of ws.children){
  if(c.type!=='FRAME') continue;
  const hots=c.children.filter(x=>String(x.name).indexOf('Hotspot')===0);
  for(const h of hots){
    total++;
    const rr=h.reactions||[];
    if(rr.length>0 && rr[0].actions && rr[0].actions[0] && rr[0].actions[0].destinationId){
      wired++;
      const dest=figma.getNodeById(rr[0].actions[0].destinationId);
      out.push(h.name+' -> '+(dest?dest.name:'?'));
    } else {
      out.push(h.name+' -> UNWIRED');
    }
  }
}
out.push('WIRED '+wired+'/'+total);
return out.join('\n');

